# التربية الإسلامية — السنة الخامسة، جميع الشعب (المعهد التربوي الوطني). المحتوى من الكتاب فقط.
BOOK = "IR_5ACDO"

def F(page, y0, y1, x0=0.05, x1=0.95, cap=""):
    return {"page": page, "rect": [x0, y0, x1, y1], "caption": cap}

def L(title, pages, objectives, intro, summary, points, application, board, applications=None):
    d = {"title": title, "match": [title], "pages": pages, "objectives": objectives, "intro": intro,
         "summary": summary, "points": points, "application": {"q": application[0], "a": application[1]}, "board": board}
    if applications:
        d["applications"] = [{"q": q, "a": a} for q, a in applications]
    return d

def S(h, lines=None, table=None, fig=None):
    d = {"h": h, "lines": lines or []}
    if table: d["table"] = table
    if fig: d["fig"] = fig
    return d

def Q(title, pages, verses_fig, words_fig, objectives, intro, summary, points, application, comment, rules, applications=None):
    """درس قرآن: الآيات وشرح الكلمات صورتان من الكتاب (الخط القرآني)، ثم التعليق والأحكام."""
    board = [S("الآيات", fig=verses_fig), S("تفسير الكلمات والعبارات", fig=words_fig),
             S("التعليق على الآيات", comment), S("بعض الأحكام والآداب المستخلصة", rules)]
    return L(title, pages, objectives, intro, summary, points, application, board, applications)

